def solve(N):
    # f[x] is the status of the position x
    # f[x] = 1 if it's a Winning position (next player can win)
    # f[x] = 0 if it's a Losing position (next player will lose)
    f = [0] * (N + 1)
    f[N] = 0 # The player who is handed N loses
    for x in range(N - 1, 0, -1):
        can_move_to_L = False
        # move to x+1
        if x + 1 <= N and f[x+1] == 0:
            can_move_to_L = True
        # move to 2x
        if 2 * x <= N and f[2*x] == 0:
            can_move_to_L = True

        if can_move_to_L:
            f[x] = 1
        else:
            f[x] = 0

    # A writes 1, so B is handed 1.
    # If f[1] == 0, B loses, so A wins (Type A).
    # If f[1] == 1, B wins, so A loses (Type B).
    return "A" if f[1] == 0 else "B"

results = []
for n in range(1, 500):
    results.append((n, solve(n)))

for n, res in results:
    if res == "B":
        print(f"N={n} is Type B")

